// ═══════════════════════════════════════════════════════════
// CONFIG HELPERS
// ═══════════════════════════════════════════════════════════
async function getConfig(gid) {
  return _configCache.fetch(gid, async () => {
    try {
      const { data, error } = await supabase.from('configs').select('*').eq('guild_id', gid).maybeSingle();
      if (error) { console.error('[getConfig]', error.message); return { guild_id: gid, ...defaultConfig }; }
      return data ? { ...defaultConfig, ...data, guild_id: gid } : { guild_id: gid, ...defaultConfig };
    } catch (e) {
      console.error('[getConfig]', e.message);
      return { guild_id: gid, ...defaultConfig };
    }
  });
}

async function setConfig(gid, cfg) {
  _configCache.delete(gid);
  try {
    const clean = {};
    for (const [k, v] of Object.entries(cfg)) if (v !== undefined && k !== 'guild_id') clean[k] = v;
    clean.guild_id = gid;
    clean.updated_at = new Date().toISOString();
    const { error } = await supabase.from('configs').upsert(clean, { onConflict: 'guild_id' });
    if (error) { console.error('[setConfig]', error.message); return false; }
    _configCache.set(gid, { ...cfg, guild_id: gid });
    return true;
  } catch (e) { console.error('[setConfig]', e.message); return false; }
}

async function getSettings(gid) {
  const cached = _settingsCache.get(gid);
  if (cached !== undefined) return cached;
  try {
    const { data } = await supabase.from('settings').select('*').eq('guild_id', gid).maybeSingle();
    return _settingsCache.set(gid, data || null);
  } catch { return null; }
}

async function patchSettings(gid, p) {
  _settingsCache.delete(gid);
  try {
    await supabase.from('settings').upsert({ guild_id: gid, ...p, updated_at: new Date().toISOString() }, { onConflict: 'guild_id' });
  } catch (e) { console.error('[patchSettings]', e.message); }
  return getSettings(gid);
}

// ═══════════════════════════════════════════════════════════
// LOCALE
// ═══════════════════════════════════════════════════════════
async function getGuildLocale(gid) {
  if (!gid) return 'pt-BR';
  const cached = _localeCache.get(gid);
  if (cached) return cached;
  try {
    const { data } = await supabase.from('guild_locale').select('locale').eq('guild_id', gid).maybeSingle();
    return _localeCache.set(gid, data?.locale || 'pt-BR');
  } catch { return 'pt-BR'; }
}
async function setGuildLocale(gid, locale) {
  const valid = ['pt-BR', 'en-US', 'es-ES'];
  if (!valid.includes(locale)) return false;
  _localeCache.delete(gid);
  try {
    await supabase.from('guild_locale').upsert({
      guild_id: gid, locale, updated_at: new Date().toISOString(),
    }, { onConflict: 'guild_id' });
    _localeCache.set(gid, locale);
    return true;
  } catch (e) { console.error('[setGuildLocale]', e.message); return false; }
}

async function getCustomer(gid, uid) {
  const { data } = await supabase.from('customers').select('*').eq('guild_id', gid).eq('user_id', uid).maybeSingle();
  if (data) return data;
  const { data: c } = await supabase.from('customers').insert({ guild_id: gid, user_id: uid }).select().single();
  return c;
}

async function ensureGuild(g) {
  try { await supabase.from('guilds').upsert({ id: g.id, name: g.name }, { onConflict: 'id' }); } catch {}
  try {
    const { data } = await supabase.from('settings').select('guild_id').eq('guild_id', g.id).maybeSingle();
    if (!data) await supabase.from('settings').insert({ guild_id: g.id });
  } catch {}
}

async function fetchMember(g, id) { try { return await g.members.fetch(id); } catch { return null; } }

async function setGuildMPToken(gid, token, publicKey = null) {
  await patchSettings(gid, { mp_access_token: token || null, mp_public_key: publicKey || null });
}
async function setFFMPToken(gid, token, publicKey = null) {
  _ffConfigCache.delete(gid);
  try {
    await supabase.from('ff_config').upsert({
      guild_id: gid, mp_access_token: token || null, mp_public_key: publicKey || null,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'guild_id' });
  } catch {}
}

// ═══════════════════════════════════════════════════════════
// PERMISSÕES
// ═══════════════════════════════════════════════════════════
async function isAdmin(mu, g) {
  const id = mu?.user?.id || mu?.id;
  if (isDeveloper(id)) return true;
  if (id === g.ownerId) return true;
  const m = await fetchMember(g, id);
  if (!m) return false;
  if (m.permissions.has(PermissionFlagsBits.Administrator)) return true;
  const c = await getConfig(g.id);
  if (c.admin_role && m.roles.cache.has(c.admin_role)) return true;
  return false;
}

async function isTicketStaff(mu, g, panelRoleId = null, typeRoleId = null) {
  const id = mu?.user?.id || mu?.id;
  if (isDeveloper(id)) return true;
  if (id === g.ownerId) return true;
  const m = await fetchMember(g, id);
  if (!m) return false;
  if (m.permissions.has(PermissionFlagsBits.Administrator)) return true;
  const c = await getConfig(g.id);
  if (typeRoleId && m.roles.cache.has(typeRoleId)) return true;
  if (panelRoleId && m.roles.cache.has(panelRoleId)) return true;
  if (c.ticket_cargo && m.roles.cache.has(c.ticket_cargo)) return true;
  return false;
}

async function isMediator(mu, g) {
  const id = mu?.user?.id || mu?.id;
  if (!id) return false;
  if (isDeveloper(id)) return true;
  if (id === g.ownerId) return true;
  const m = await fetchMember(g, id);
  if (!m) return false;
  if (m.permissions.has(PermissionFlagsBits.Administrator)) return true;
  const ff = await ffGetConfig(g.id);
  if (ff?.mediator_role_id && m.roles.cache.has(ff.mediator_role_id)) return true;
  if (ff?.olhinho_role_id && m.roles.cache.has(ff.olhinho_role_id)) return true;
  return false;
}

async function shopIsAdmin(i) {
  if (!i.guild) return false;
  if (isDeveloper(i.user?.id)) return true;
  if (i.user?.id === i.guild.ownerId) return true;
  if (!i.member) {
    try { i.member = await i.guild.members.fetch(i.user.id); } catch { return false; }
  }
  if (!i.member) return false;
  if (i.member.permissions?.has?.('Administrator')) return true;
  const s = await getSettings(i.guild.id);
  return [s?.admin_role_id, s?.manager_role_id].filter(Boolean).some(r => i.member.roles.cache.has(r));
}
async function requireShopAdmin(i) {
  if (await shopIsAdmin(i)) return true;
  await i.reply({ content: `${E.x} Sem permissão.`, flags: EPHEMERAL }).catch(() => {});
  return false;
}

// ═══════════════════════════════════════════════════════════
// LOJA v2 — entrega automática, confirmação de pagamento, cupom e segurança dos pedidos
//  • aprovar pedido agora ENTREGA o estoque (antes só mudava o status e nada era entregue)
//  • Mercado Pago é conferido sozinho a cada 30s (antes ninguém consultava o pagamento)
//  • estoque reservado de forma atômica (dois compradores não pegam o mesmo item)
//  • cupom: 1 por pedido, validade/limite/mínimo, uso contado só na entrega
//  • todo botão de pedido confere dono, servidor e status
// ═══════════════════════════════════════════════════════════
const ORDER_OPEN_STATES = ['open', 'awaiting_payment', 'awaiting_approval'];
const round2 = (n) => Math.round(Number(n || 0) * 100) / 100;
const _storeNotified = new Set();

function couponProblem(cp, subtotal) {
  if (!cp) return 'Cupom inválido.';
  if (cp.active === false) return 'Cupom desativado.';
  if (cp.expires_at && new Date(cp.expires_at).getTime() < Date.now()) return 'Cupom expirado.';
  if (cp.max_uses && Number(cp.uses || 0) >= Number(cp.max_uses)) return 'Cupom esgotado.';
  if (cp.min_value && subtotal < Number(cp.min_value)) return `Pedido mínimo de ${brl(cp.min_value)} para este cupom.`;
  return null;
}
function couponDiscount(cp, subtotal) {
  const raw = cp.type === 'percent' ? subtotal * (Number(cp.value) / 100) : Number(cp.value);
  return round2(Math.min(Math.max(Number.isFinite(raw) ? raw : 0, 0), subtotal));
}

// Recalcula subtotal/desconto/total a partir dos itens + cupom (única fonte de verdade do valor)
async function recalcOrder(oid) {
  const { data: o } = await supabase.from('orders').select('id, guild_id, coupon_code').eq('id', oid).maybeSingle();
  if (!o) return { subtotal: 0, discount: 0, total: 0 };
  const { data: its } = await supabase.from('order_items').select('total').eq('order_id', oid);
  const subtotal = round2((its || []).reduce((a, x) => a + Number(x.total || 0), 0));
  let discount = 0, coupon = o.coupon_code || null;
  if (coupon) {
    const { data: cp } = await supabase.from('coupons').select('*').eq('guild_id', o.guild_id).eq('code', coupon).maybeSingle();
    if (couponProblem(cp, subtotal)) coupon = null; else discount = couponDiscount(cp, subtotal);
  }
  const total = round2(Math.max(0, subtotal - discount));
  await supabase.from('orders').update({ subtotal, discount, total, coupon_code: coupon }).eq('id', oid);
  return { subtotal, discount, total, coupon };
}

// Carrega o pedido garantindo: mesmo servidor, dono (ou admin da loja) e status permitido
async function getOrderFor(i, oid, { states = null, ownerOnly = true } = {}) {
  if (!i.guild) return { err: `${E.x} Use em um servidor.` };
  const { data: o } = await supabase.from('orders').select('*').eq('id', oid).eq('guild_id', i.guild.id).maybeSingle();
  if (!o) return { err: `${E.x} Pedido não encontrado.` };
  const isAdm = await shopIsAdmin(i).catch(() => false);
  if (ownerOnly && o.user_id !== i.user.id && !isAdm) return { err: `${E.x} Este pedido não é seu.` };
  if (states && !states.includes(o.status)) return { err: `${E.xAlt} Este pedido não pode mais ser alterado (status: **${o.status}**).` };
  return { o, isAdm };
}

// Reserva N itens do estoque de forma atômica. Só marca 'sold' o que ainda está 'available'.
async function claimInventory(productId, qty, orderId) {
  const { data: avail } = await supabase.from('inventory').select('id').eq('product_id', productId).eq('status', 'available').order('id', { ascending: true }).limit(qty);
  if (!avail || avail.length < qty) return { ok: false, have: avail?.length || 0 };
  const ids = avail.map(x => x.id);
  let upd = await supabase.from('inventory').update({ status: 'sold', order_id: orderId, sold_at: new Date().toISOString() }).in('id', ids).eq('status', 'available').select('id, content');
  if (upd.error) {
    // tabelas sem as colunas order_id/sold_at: marca só o status
    upd = await supabase.from('inventory').update({ status: 'sold' }).in('id', ids).eq('status', 'available').select('id, content');
  }
  if (upd.error) throw new Error(upd.error.message);
  const got = upd.data || [];
  if (got.length < qty) {
    // outro comprador levou parte: devolve o que pegamos e avisa falta de estoque
    if (got.length) await supabase.from('inventory').update({ status: 'available' }).in('id', got.map(x => x.id));
    return { ok: false, have: Math.max(0, avail.length - (qty - got.length)) };
  }
  return { ok: true, items: got };
}

// Confere o carrinho contra o estoque (só para produtos que têm estoque cadastrado)
async function orderStockShortfall(items) {
  for (const it of items || []) {
    const qty = Math.max(1, Number(it.quantity || 1));
    const { count: total } = await supabase.from('inventory').select('id', { count: 'exact', head: true }).eq('product_id', it.product_id);
    if (!total) continue; // sem estoque cadastrado = entrega manual da staff
    const { count: have } = await supabase.from('inventory').select('id', { count: 'exact', head: true }).eq('product_id', it.product_id).eq('status', 'available');
    if ((have || 0) < qty) return { name: it.product_name, have: have || 0, need: qty };
  }
  return null;
}

async function notifyStoreStaff(guild, text, key = null) {
  try {
    if (key) { if (_storeNotified.has(key)) return; _storeNotified.add(key); if (_storeNotified.size > 500) _storeNotified.clear(); }
    const s = await getSettings(guild.id);
    const ch = s?.log_channel_id ? (guild.channels.cache.get(s.log_channel_id) || await guild.channels.fetch(s.log_channel_id).catch(() => null)) : null;
    if (ch?.isTextBased?.()) await ch.send({ content: String(text).slice(0, 1900), allowedMentions: { parse: [] } }).catch(() => {});
  } catch {}
}

// Entrega o pedido. Idempotente: o "claim" troca o status para delivered só se ainda estiver aberto.
async function deliverOrder(guild, oid, { by = null } = {}) {
  const { data: prev } = await supabase.from('orders').select('*').eq('id', oid).eq('guild_id', guild.id).maybeSingle();
  if (!prev) return { ok: false, error: 'Pedido não encontrado.' };
  if (!ORDER_OPEN_STATES.includes(prev.status)) return { ok: false, error: `Pedido já está **${prev.status}**.` };

  const { data: claimed } = await supabase.from('orders')
    .update({ status: 'delivered', paid_at: prev.paid_at || new Date().toISOString() })
    .eq('id', oid).eq('status', prev.status).select('id').maybeSingle();
  if (!claimed) return { ok: false, error: 'Pedido já está sendo processado.' };

  const groups = [];
  const rollback = async () => {
    for (const g of groups) await supabase.from('inventory').update({ status: 'available' }).in('id', g.ids).catch(() => {});
    await supabase.from('orders').update({ status: prev.status }).eq('id', oid).catch(() => {});
  };

  // ── etapa 1: reservar estoque (se falhar, desfaz tudo) ──
  const lines = [], manual = [];
  try {
    const { data: items } = await supabase.from('order_items').select('*').eq('order_id', oid);
    if (!items?.length) { await rollback(); return { ok: false, error: 'Pedido sem itens.' }; }
    for (const it of items) {
      const qty = Math.max(1, Number(it.quantity || 1));
      const { data: prod } = await supabase.from('products').select('delivery_type').eq('id', it.product_id).maybeSingle();
      const { count } = await supabase.from('inventory').select('id', { count: 'exact', head: true }).eq('product_id', it.product_id);
      if (!count) { manual.push(`${it.product_name} ×${qty}`); continue; }
      const r = await claimInventory(it.product_id, qty, oid);
      if (!r.ok) {
        await rollback();
        return { ok: false, noStock: true, error: `Sem estoque suficiente de **${it.product_name}** (${r.have}/${qty}). O pedido continua aberto.` };
      }
      groups.push({ ids: r.items.map(x => x.id) });
      lines.push({ name: it.product_name, type: prod?.delivery_type || 'key', contents: r.items.map(x => String(x.content ?? '')) });
    }
  } catch (e) {
    console.error('[LOJA-ENTREGA]', oid, e.message);
    await rollback();
    return { ok: false, error: `Falha ao reservar estoque: ${e.message}` };
  }

  // ── etapa 2: avisar o cliente (nunca desfaz a entrega) ──
  let dmOk = false;
  try {
    const body = lines.map(l => {
      const txt = l.contents.join('\n').slice(0, 900);
      const isLink = /^https?:\/\//i.test(txt.trim()) && l.contents.length === 1;
      return `**${l.name}**\n${isLink ? txt : '```\n' + txt + '\n```'}`;
    }).join('\n').slice(0, 3800);
    const manualTxt = manual.length ? `\n\n${E.suporte} **Entrega manual:** a staff vai enviar ${manual.join(', ')} neste canal em breve.` : '';
    const eMsg = new EmbedBuilder().setColor('#22c55e').setTitle(`${E.entrega} Pedido #${oid} entregue!`)
      .setDescription(`${body || '*Nenhum item automático neste pedido.*'}${manualTxt}`.slice(0, 4000))
      .setFooter({ text: guild.name }).setTimestamp();

    const user = await client.users.fetch(prev.user_id).catch(() => null);
    if (user && lines.length) dmOk = await user.send({ embeds: [eMsg] }).then(() => true).catch(() => false);

    const ch = prev.channel_id ? (guild.channels.cache.get(prev.channel_id) || await guild.channels.fetch(prev.channel_id).catch(() => null)) : null;
    if (ch?.isTextBased?.()) {
      const confirm = new EmbedBuilder().setColor('#22c55e').setTitle(`${E.check} Pedido #${oid} concluído`)
        .setDescription(lines.length && dmOk ? `Enviamos sua entrega por **DM**. ${manualTxt}`.trim() : `${body}${manualTxt}`.slice(0, 4000) || 'Concluído.');
      await ch.send({ content: `<@${prev.user_id}>`, embeds: [confirm] }).catch(() => {});
    }

    const st = await getSettings(guild.id);
    if (st?.customer_role_id) {
      const m = await guild.members.fetch(prev.user_id).catch(() => null);
      if (m) await m.roles.add(st.customer_role_id).catch(() => {});
    }
    if (prev.coupon_code) {
      const { data: cp } = await supabase.from('coupons').select('id, uses').eq('guild_id', guild.id).eq('code', prev.coupon_code).maybeSingle();
      if (cp) await supabase.from('coupons').update({ uses: Number(cp.uses || 0) + 1 }).eq('id', cp.id);
    }
    await notifyStoreStaff(guild, `${E.check} Pedido **#${oid}** entregue — ${brl(prev.total)} — <@${prev.user_id}>${by ? ` (aprovado por <@${by}>)` : ' (automático)'}${manual.length ? `\n${E.suporte} **Entrega manual pendente:** ${manual.join(', ')}` : ''}${lines.length && !dmOk ? '\n⚠️ DM fechada: conteúdo enviado no canal do pedido.' : ''}`);
  } catch (e) { console.error('[LOJA-ENTREGA-MSG]', oid, e.message); }

  return { ok: true, dmOk, manual, lines: lines.length };
}

// Consulta o Mercado Pago e valida valor/referência antes de liberar a entrega
async function checkMpPayment(guild, o) {
  const st = await getSettings(guild.id);
  const token = st?.mp_access_token || process.env.MP_ACCESS_TOKEN || null;
  if (!token || !o.mp_payment_id) return { state: 'unknown' };
  const pay = await consultarPixMercadoPago(o.mp_payment_id, token);
  if (!pay || pay.error) return { state: 'error', error: pay?.error || 'sem resposta' };
  if (pay.status === 'approved') {
    const paid = Number(pay.transaction_amount || 0);
    const refOk = !pay.external_reference || String(pay.external_reference) === String(o.id);
    if (Math.abs(paid - Number(o.total)) > 0.01 || !refOk) return { state: 'mismatch', paid };
    return { state: 'approved' };
  }
  if (['cancelled', 'rejected', 'refunded', 'charged_back'].includes(pay.status)) return { state: 'dead', status: pay.status };
  return { state: 'pending', status: pay.status };
}

async function cancelMpPayment(guild, o) {
  try {
    const st = await getSettings(guild.id);
    const token = st?.mp_access_token || process.env.MP_ACCESS_TOKEN || null;
    if (!token || !o.mp_payment_id) return;
    await fetch(`https://api.mercadopago.com/v1/payments/${o.mp_payment_id}`, {
      method: 'PUT', headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'cancelled' }),
    });
  } catch {}
}

async function closeOrderChannel(guild, o, text) {
  try {
    const ch = o.channel_id ? (guild.channels.cache.get(o.channel_id) || await guild.channels.fetch(o.channel_id).catch(() => null)) : null;
    if (!ch) return;
    if (text) await ch.send({ content: text }).catch(() => {});
    setTimeout(() => ch.delete().catch(() => {}), 8000);
  } catch {}
}

async function storeWorkerTick() {
  // 1) confere pagamentos Mercado Pago pendentes
  const since = new Date(Date.now() - 3 * 3600 * 1000).toISOString();
  const { data: ords } = await supabase.from('orders').select('*')
    .eq('payment_gateway', 'mercadopago').in('status', ['awaiting_payment', 'awaiting_approval'])
    .gte('created_at', since).limit(50);
  for (const o of ords || []) {
    const g = client.guilds.cache.get(o.guild_id);
    if (!g) continue;
    const r = await checkMpPayment(g, o);
    if (r.state === 'approved') {
      const d = await deliverOrder(g, o.id);
      if (!d.ok && !/já está/.test(d.error)) await notifyStoreStaff(g, `🚨 Pedido **#${o.id}** PAGO mas não entregue: ${d.error}`, `nostock:${o.id}`);
    } else if (r.state === 'mismatch') {
      await notifyStoreStaff(g, `🚨 Pedido **#${o.id}**: valor pago (${brl(r.paid)}) diferente do pedido (${brl(o.total)}). Confira no Mercado Pago e aprove manualmente se estiver certo.`, `mismatch:${o.id}`);
    } else if (r.state === 'dead') {
      await supabase.from('orders').update({ status: 'cancelled' }).eq('id', o.id).in('status', ['awaiting_payment', 'awaiting_approval']);
      await closeOrderChannel(g, o, `${E.x} Pagamento ${r.status === 'refunded' ? 'estornado' : 'cancelado'} no Mercado Pago. Pedido cancelado.`);
    }
    await sleep(300);
  }
  // 2) expira pagamentos MP não pagos (2h) e carrinhos abandonados (6h)
  const cut2h = new Date(Date.now() - 2 * 3600 * 1000).toISOString();
  const { data: stale } = await supabase.from('orders').select('*').eq('payment_gateway', 'mercadopago').eq('status', 'awaiting_payment').lt('created_at', cut2h).limit(25);
  for (const o of stale || []) {
    const g = client.guilds.cache.get(o.guild_id); if (!g) continue;
    const r = await checkMpPayment(g, o);
    if (r.state === 'approved') { await deliverOrder(g, o.id); continue; }
    await supabase.from('orders').update({ status: 'cancelled' }).eq('id', o.id).eq('status', 'awaiting_payment');
    await cancelMpPayment(g, o);
    await closeOrderChannel(g, o, `${E.carregando} O PIX expirou sem pagamento e o pedido foi cancelado.`);
  }
  const cut6h = new Date(Date.now() - 6 * 3600 * 1000).toISOString();
  const { data: old } = await supabase.from('orders').select('id, guild_id, channel_id').eq('status', 'open').lt('created_at', cut6h).limit(25);
  for (const o of old || []) {
    const g = client.guilds.cache.get(o.guild_id); if (!g) continue;
    await supabase.from('orders').update({ status: 'cancelled' }).eq('id', o.id).eq('status', 'open');
    await closeOrderChannel(g, o, `${E.carregando} Carrinho abandonado. Canal fechado.`);
  }
}

let _storeWorkersStarted = false;
function startStoreWorkers() {
  if (_storeWorkersStarted) return;
  _storeWorkersStarted = true;
  let running = false;
  const run = async () => {
    if (running) return; running = true;
    try { await storeWorkerTick(); } catch (e) { console.error('[LOJA-WORKER]', e.message); } finally { running = false; }
  };
  const t = setInterval(run, 30000); t.unref?.();
  setTimeout(run, 20000).unref?.();
  console.log('🛒 [LOJA] Verificação automática de pagamentos ativa (30s).');
}

// ═══════════════════════════════════════════════════════════
// PREMIUM
// ═══════════════════════════════════════════════════════════
async function isPremium(gid) {
  try {
    const { data: fp } = await supabase.from('force_premium').select('scope,target_id,permanent,expires_at').eq('scope', 'guild').eq('target_id', gid).maybeSingle();
    if (fp) {
      if (fp.permanent) return true;
      if (fp.expires_at && new Date(fp.expires_at) > new Date()) return true;
      await supabase.from('force_premium').delete().eq('scope', 'guild').eq('target_id', gid);
    }
  } catch {}
  const c = await getConfig(gid);
  if (!c.is_premium) return false;
  if (c.premium_expires_at && new Date(c.premium_expires_at) <= new Date()) {
    c.is_premium = false; c.premium_expires_at = null;
    await setConfig(gid, c);
    return false;
  }
  return true;
}

async function getPremiumTier(gid) {
  try {
    const { data: fp } = await supabase.from('force_premium').select('tier,permanent,expires_at').eq('scope', 'guild').eq('target_id', gid).maybeSingle();
    if (fp && (fp.permanent || (fp.expires_at && new Date(fp.expires_at) > new Date()))) return fp.tier || 'unlimited';
  } catch {}
  const c = await getConfig(gid);
  if (!c.is_premium) return null;
  if (c.premium_expires_at && new Date(c.premium_expires_at) <= new Date()) return null;
  return c.premium_tier || 'basic';
}

async function requirePremiumTier(i, feature) {
  if (!i.guild) return false;
  const requiredTier = featureMinTier(feature);
  const userTier = await getPremiumTier(i.guild.id);
  if (userTier && tierAtLeast(userTier, requiredTier)) return true;

  const prettyNames = {
    musica: '🎵 Sistema de música', paineis_ilimitados: '🎨 Painéis ilimitados',
    custom_embeds: '🖌️ Embeds customizados', automacao: '⚙️ Automação',
    automacao_basica: '⚙️ Automação básica', automacao_avancada: '⚡ Automação avançada',
    simulador: '🎬 Simulador de fluxo', multi_idioma: '🌐 Multi-idioma',
    backup_automatico: '💾 Backup automático', analytics_basico: '📊 Analytics básico',
    analytics_avancado: '📈 Analytics avançado', versiculo_diario: '📖 Versículo do dia',
    custom_dominio_pix: '💳 Domínio PIX customizado', streamer_ilimitado: '🎥 Streamers ilimitados',
    mediador_ilimitado: '🛡️ Mediadores ilimitados', tickets_ilimitados: '🎫 Tickets ilimitados',
    paineis_loja_extra: '🛒 Painéis de loja extras', criar_servidor_loja: '🏗️ Criar servidor loja',
    custom_bot_branding: '🎨 Branding customizado', api_webhook: '🔗 API Webhook',
  };
  const titulo = prettyNames[feature] || feature;
  const tierMeta = PREMIUM_TIERS[requiredTier] || PREMIUM_TIERS.premium;
  const atualTxt = userTier ? `Tier atual: **${PREMIUM_TIERS[userTier]?.label || userTier}**` : 'Sem premium ativo';

  await i.reply({
    embeds: [new EmbedBuilder().setTitle(`${tierMeta.emoji} Recurso ${tierMeta.label}`).setColor(tierMeta.color)
      .setDescription(`**${titulo}** é um recurso **${tierMeta.label}**.\n\n> ${atualTxt}\n> Necessário: **${tierMeta.label}**\n\n🚀 Resgate com \`/perfil resgatar\` ou peça pra staff.`)
      .setFooter({ text: 'Frio Bot • Premium' })],
    flags: EPHEMERAL,
  }).catch(() => {});
  return false;
}

async function requirePremium(i, feature = 'Este recurso') {
  return requirePremiumTier(i, feature);
}

