async function buscarVersiculoBiblia() {
  try {
    const r = await fetch('https://www.abibliadigital.com.br/api/verses/nvi/random', {
      headers: { 'User-Agent': 'FrioBot/6.8.0' },
    });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const d = await r.json();
    if (d?.text && d?.book?.name && d?.chapter && d?.number) {
      return { ref: `${d.book.name} ${d.chapter}:${d.number}`, txt: d.text };
    }
    throw new Error('Formato inválido');
  } catch (e) {
    console.warn('[VERSICULO] API falhou, usando fallback:', e.message);
    return VERSICULOS_FALLBACK[Math.floor(Math.random() * VERSICULOS_FALLBACK.length)];
  }
}

function hashVersiculo(v) {
  return crypto.createHash('md5').update(`${v.ref}|${v.txt}`).digest('hex').slice(0, 16);
}

async function enviarVersiculoDia(guildId, channelId, opts = {}) {
  try {
    const g = client.guilds.cache.get(guildId);
    if (!g) return false;
    const ch = g.channels.cache.get(channelId) || await g.channels.fetch(channelId).catch(() => null);
    if (!ch || !ch.isTextBased?.()) return false;

    const v = await buscarVersiculoBiblia();
    const e = new EmbedBuilder()
      .setTitle(`${E.jesus} Versículo do Dia`)
      .setColor('#FEE75C')
      .setDescription(`*"${v.txt}"*\n\n— **${v.ref}**`)
      .setFooter({ text: opts.footer || `Frio Bot • ${new Date().toLocaleDateString('pt-BR')}` })
      .setTimestamp();

    if (g.iconURL()) e.setThumbnail(g.iconURL({ size: 256 }));

    await ch.send({ content: opts.ping || null, embeds: [e] }).catch(() => {});

    await supabase.from('configs').upsert({
      guild_id: guildId,
      versiculo_last_sent: new Date().toISOString(),
      versiculo_last_hash: hashVersiculo(v),
      updated_at: new Date().toISOString(),
    }, { onConflict: 'guild_id' });
    _configCache.delete(guildId);

    try {
      await supabase.from('daily_verses_history').insert({
        guild_id: guildId,
        verse_ref: v.ref,
        verse_text: v.txt,
        verse_hash: hashVersiculo(v),
      });
    } catch {}

    return true;
  } catch (e) {
    console.error('[VERSICULO]', guildId, e.message);
    return false;
  }
}

async function checkVersiculosDia() {
  try {
    const hora = new Date().getHours();
    const { data: cfgs } = await supabase.from('configs')
      .select('guild_id,versiculo_channel,versiculo_hora,versiculo_last_sent')
      .eq('versiculo_ativo', true)
      .not('versiculo_channel', 'is', null);

    for (const c of cfgs || []) {
      if ((c.versiculo_hora ?? 8) !== hora) continue;
      if (c.versiculo_last_sent) {
        const last = new Date(c.versiculo_last_sent);
        const hoje = new Date();
        if (last.toDateString() === hoje.toDateString()) continue;
      }
      await enviarVersiculoDia(c.guild_id, c.versiculo_channel, {});
      await sleep(3000);
    }
  } catch (e) { console.error('[VERSICULO-LOOP]', e.message); }
}

// ═══════════════════════════════════════════════════════════
// ANALYTICS — trackFeatureUsage + relatórios avançados
// ═══════════════════════════════════════════════════════════
async function trackFeatureUsage(gid, feature) {
  if (!gid || !feature) return;
  try {
    const { data: ex } = await supabase.from('guild_feature_usage')
      .select('id,uses').eq('guild_id', gid).eq('feature', feature).maybeSingle();

    if (ex) {
      await supabase.from('guild_feature_usage')
        .update({ uses: Number(ex.uses || 0) + 1, last_used: new Date().toISOString() })
        .eq('id', ex.id);
    } else {
      await supabase.from('guild_feature_usage')
        .insert({ guild_id: gid, feature, uses: 1 });
    }
  } catch {}
}

async function getAnalyticsAdvanced(gid) {
  const since7d = new Date(Date.now() - 7 * 86400000).toISOString();

  const [usageRes, betsRes, ordersRes, ticketsRes, coinsRes] = await Promise.allSettled([
    supabase.from('guild_feature_usage').select('*').eq('guild_id', gid).order('uses', { ascending: false }).limit(20),
    supabase.from('ff_matches').select('id', { count: 'exact', head: true }).eq('guild_id', gid).gte('created_at', since7d),
    supabase.from('orders').select('id,total,status').eq('guild_id', gid).gte('created_at', since7d),
    supabase.from('ticket_data').select('id', { count: 'exact', head: true }).eq('guild_id', gid).gte('created_at', since7d),
    supabase.from('ff_logs').select('details').eq('guild_id', gid).eq('category', 'coins').gte('created_at', since7d),
  ]);

  const usage = usageRes.status === 'fulfilled' ? (usageRes.value.data || []) : [];
  const bets7d = betsRes.status === 'fulfilled' ? (betsRes.value.count || 0) : 0;
  const ordersList = ordersRes.status === 'fulfilled' ? (ordersRes.value.data || []) : [];
  const fat7d = ordersList.filter(o => o.status === 'delivered').reduce((a, o) => a + Number(o.total || 0), 0);
  const tickets7d = ticketsRes.status === 'fulfilled' ? (ticketsRes.value.count || 0) : 0;
  const coinsMov7d = coinsRes.status === 'fulfilled'
    ? (coinsRes.value.data || []).reduce((a, l) => a + Math.abs(Number(l.details?.amount || 0)), 0)
    : 0;

  return { usage, bets7d, orders7d: ordersList.length, fat7d, tickets7d, coinsMov7d };
}

// ═══════════════════════════════════════════════════════════
// VOZ
// ═══════════════════════════════════════════════════════════
async function salvarCanalVoz(g, c) {
  try {
    await supabase.from('bot_voice').upsert({ guild_id: g, channel_id: c, updated_at: new Date().toISOString() });
  } catch {}
}
async function removerCanalVoz(g) {
  try { await supabase.from('bot_voice').delete().eq('guild_id', g); } catch {}
}
async function getCanalVozSalvo(g) {
  try {
    const { data } = await supabase.from('bot_voice').select('channel_id').eq('guild_id', g).maybeSingle();
    return data?.channel_id || null;
  } catch { return null; }
}

async function entrarNaCall(g, cid, player = null) {
  try {
    const ch = g.channels.cache.get(cid) || await g.channels.fetch(cid).catch(() => null);
    if (!ch || ch.type !== ChannelType.GuildVoice) return null;

    const me = g.members.me;
    if (!ch.permissionsFor(me)?.has(PermissionFlagsBits.Connect)) {
      console.warn(`[VOZ] Sem permissão pra entrar em ${ch.name} (${g.name})`);
      return null;
    }

    const conn = joinVoiceChannel({
      channelId: ch.id,
      guildId: g.id,
      adapterCreator: g.voiceAdapterCreator,
      selfDeaf: true,
      selfMute: true,
    });
    if (player) conn.subscribe(player);

    conn.on(VoiceConnectionStatus.Disconnected, async () => {
      try {
        await Promise.race([
          entersState(conn, VoiceConnectionStatus.Signalling, 5000),
          entersState(conn, VoiceConnectionStatus.Connecting, 5000),
        ]);
      } catch {
        conn.destroy();
        setTimeout(async () => {
          const s = await getCanalVozSalvo(g.id);
          if (s) entrarNaCall(g, s, player);
        }, 5000);
      }
    });

    conn.on('error', (e) => console.error(`[VOZ-ERR] ${g.id}:`, e.message));
    return conn;
  } catch (e) { console.error('[VOZ]', e.message); return null; }
}

async function reconectarTodasCalls() {
  try {
    const { data } = await supabase.from('bot_voice').select('*');
    for (const r of data || []) {
      const g = client.guilds.cache.get(r.guild_id);
      if (g) try { await entrarNaCall(g, r.channel_id); } catch {}
      await sleep(500);
    }
  } catch {}
}

// ═══════════════════════════════════════════════════════════
// 🎵 MÚSICA — v2 (play-dl + @discordjs/voice)
// Correções em relação à v1:
//  • "Parar" não reinicia mais a fila (o Idle disparado pelo stop() tocava a próxima música)
//  • erro de stream não avança 2 músicas (evento 'error' + 'Idle' somavam)
//  • pular com player pausado agora avança
//  • reconecta a call 24/7 quando a música acaba
//  • sai da call vazia e limpa a fila se o bot for desconectado/expulso
//  • player reassinado quando a conexão é recriada (antes ficava mudo)
//  • suporte a playlist do YouTube, limite de fila e bloqueio de live
//  • qualquer membro na call pode usar (antes só admin pelo painel)
// ═══════════════════════════════════════════════════════════
const MUSIC_MAX_QUEUE = 100;
const MUSIC_CLEANUP_MS = 30000;
const MUSIC_EMPTY_MS = 30000;
const MUSIC_STREAM_TIMEOUT_MS = 25000;
const _musicSearchCache = new Map();
const _musicCleanupTimers = new Map();
const _musicEmptyTimers = new Map();

function getQueue(gid) {
  if (!musicQueues.has(gid)) {
    musicQueues.set(gid, {
      songs: [], player: null, connection: null, textChannel: null,
      currentSong: null, loopMode: 'off', volume: 100, failed: 0,
      startedAt: 0, paused: false,
      destroyed: false, advancing: false, skipped: false, currentFailed: false, npMessage: null,
    });
  }
  return musicQueues.get(gid);
}

function _clearMusicTimers(gid) {
  for (const m of [_musicCleanupTimers, _musicEmptyTimers]) {
    const t = m.get(gid); if (t) { clearTimeout(t); m.delete(gid); }
  }
}

// Volta o bot para a call 24/7 do servidor (se houver) depois que a música termina
async function _restoreVoice247(gid) {
  try {
    const g = client.guilds.cache.get(gid);
    if (!g) return;
    const saved = await getCanalVozSalvo(gid);
    if (saved && !getVoiceConnection(gid)) await entrarNaCall(g, saved);
  } catch (e) { console.error('[MUSIC-247]', e.message); }
}

async function destroyQueue(gid, reason = 'manual') {
  const q = musicQueues.get(gid);
  if (!q) return;

  // ORDEM IMPORTA: marca como destruída e remove do mapa ANTES de parar o player.
  // player.stop() emite 'Idle' de forma síncrona e o handler antigo chamava tocarProxima().
  q.destroyed = true;
  musicQueues.delete(gid);
  _clearMusicTimers(gid);

  q.songs = [];
  q.currentSong = null;
  try { q.player?.removeAllListeners(); } catch {}
  try { q.player?.stop(true); } catch {}
  try { if (q.connection && q.connection.state.status !== VoiceConnectionStatus.Destroyed) q.connection.destroy(); } catch {}
  try { q.npMessage?.edit({ components: [] }).catch(() => {}); } catch {}

  if (q.textChannel && !['stop manual', 'silent'].includes(reason)) {
    q.textChannel.send({
      embeds: [new EmbedBuilder().setColor('#808080').setDescription(`${E.sair} Player encerrado (${reason}).`)],
    }).catch(() => {});
  }
  await _restoreVoice247(gid);
}

function scheduleQueueCleanup(gid) {
  const existing = _musicCleanupTimers.get(gid);
  if (existing) clearTimeout(existing);
  const timer = setTimeout(async () => {
    _musicCleanupTimers.delete(gid);
    const q = musicQueues.get(gid);
    if (!q || q.destroyed) return;
    if (!q.currentSong && !q.songs.length) await destroyQueue(gid, 'fila vazia');
  }, MUSIC_CLEANUP_MS);
  _musicCleanupTimers.set(gid, timer);
}

function _esc(s) { return String(s || '').replace(/[\[\]*_`~|>]/g, '').slice(0, 150); }

function musicControlRow() {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('mus_pause').setLabel('Pausar').setEmoji(E.carregando).setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId('mus_skip').setLabel('Pular').setEmoji(E.proximo).setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId('mus_stop').setLabel('Parar').setEmoji(E.lixo).setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId('mus_loop').setLabel('Loop').setEmoji(E.seta).setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('mus_queue').setLabel('Fila').setEmoji(E.lista).setStyle(ButtonStyle.Secondary),
  );
}

function buildNowPlayingEmbed(q, song) {
  const e = new EmbedBuilder().setColor('#1DB954')
    .setTitle(`${E.emote8k} Tocando agora`)
    .setDescription(`**${isValidUrl(song.url) ? `[${_esc(song.title)}](${song.url})` : _esc(song.title)}**`)
    .addFields(
      { name: 'Duração', value: `\`${song.duration || 'ao vivo?'}\``, inline: true },
      { name: 'Pedido por', value: song.author ? `<@${song.author}>` : '—', inline: true },
      { name: 'Na fila', value: String(q.songs.length), inline: true },
    )
    .setFooter({ text: `Loop: ${q.loopMode === 'off' ? 'desligado' : q.loopMode === 'song' ? 'música' : 'fila'} • Volume ${q.volume}%` });
  const th = isValidUrl(song.thumb) ? song.thumb : null;
  if (th) e.setThumbnail(th);
  return e;
}

async function _createMusicResource(song, volume) {
  if (!playdl) throw new Error('play-dl não instalado');
  if (!song?.url || !isValidUrl(song.url)) throw new Error('URL inválida');
  const st = await Promise.race([
    playdl.stream(song.url, { quality: 0, discordPlayerCompatibility: true }),
    new Promise((_, rej) => setTimeout(() => rej(new Error('tempo esgotado ao abrir o áudio')), MUSIC_STREAM_TIMEOUT_MS)),
  ]);
  const r = createAudioResource(st.stream, { inputType: st.type, inlineVolume: true });
  r.volume?.setVolume(Math.max(0, Math.min(2, volume / 100)));
  return r;
}

// Avança para a próxima música. Idempotente: chamadas concorrentes são ignoradas (q.advancing).
async function tocarProxima(gid) {
  const q = musicQueues.get(gid);
  if (!q || q.destroyed || !q.player || q.advancing) return;
  q.advancing = true;
  try {
    for (;;) {
      if (q.destroyed) return;

      if (q.failed >= 5) {
        q.textChannel?.send({ embeds: [new EmbedBuilder().setColor('#FF5555')
          .setDescription(`${E.xAlt} Muitas músicas falharam em sequência. Parando o player.`)] }).catch(() => {});
        q.failed = 0;
        await destroyQueue(gid, 'falhas');
        return;
      }

      // loop de música: repete a atual, exceto se ela falhou ou o usuário pediu para pular
      if (q.loopMode === 'song' && q.currentSong && !q.currentFailed && !q.skipped) q.songs.unshift(q.currentSong);
      q.skipped = false;

      if (!q.songs.length) {
        q.currentSong = null;
        try { q.npMessage?.edit({ components: [] }).catch(() => {}); } catch {}
        q.npMessage = null;
        scheduleQueueCleanup(gid);
        return;
      }

      const song = q.songs.shift();
      q.currentSong = song;
      q.currentFailed = false;
      if (q.loopMode === 'queue') q.songs.push(song);

      try {
        const res = await _createMusicResource(song, q.volume);
        if (q.destroyed) return;
        q.player.play(res);
        q.failed = 0;
        q.startedAt = Date.now();
        q.paused = false;
        _clearMusicTimers(gid);

        try { q.npMessage?.edit({ components: [] }).catch(() => {}); } catch {}
        q.npMessage = null;
        if (q.textChannel) {
          q.npMessage = await q.textChannel.send({ embeds: [buildNowPlayingEmbed(q, song)], components: [musicControlRow()] }).catch(() => null);
        }
        return;
      } catch (e) {
        console.error('[MUSIC]', song?.title, '→', e.message);
        q.failed++;
        q.currentFailed = true;
        // loop de fila: tira a música quebrada de volta da fila para não travar em ciclo
        if (q.loopMode === 'queue') { const ix = q.songs.lastIndexOf(song); if (ix >= 0) q.songs.splice(ix, 1); }
        q.textChannel?.send({ embeds: [new EmbedBuilder().setColor('#FF5555')
          .setDescription(`${E.xAlt} Não consegui tocar **${_esc(song?.title)}** (${_esc(e.message)}). Pulando...`)] }).catch(() => {});
        await sleep(800);
      }
    }
  } finally {
    q.advancing = false;
  }
}

// Resolve link/busca em uma ou mais músicas. Aceita vídeo, playlist do YouTube ou texto de busca.
async function resolveMusic(query, authorId, maxItems = MUSIC_MAX_QUEUE) {
  if (!playdl) throw new Error('Sistema de música indisponível (play-dl não instalado).');
  const text = String(query || '').trim().slice(0, 300);
  if (!text) throw new Error('Informe o nome da música ou um link.');

  const mk = (v) => ({
    title: v.title || 'Sem título', url: v.url, duration: v.durationRaw || null,
    author: authorId, thumb: v.thumbnails?.[v.thumbnails.length - 1]?.url || v.thumbnails?.[0]?.url || null,
  });

  const cacheKey = text.toLowerCase();
  const cached = _musicSearchCache.get(cacheKey);
  if (cached && Date.now() - cached.at < 5 * 60 * 1000) return { songs: [{ ...cached.data, author: authorId }], playlist: null };

  try {
    if (isValidUrl(text)) {
      const kind = playdl.yt_validate(text);
      if (kind === 'playlist' || (kind === 'video' && /[?&]list=/.test(text) && /\/playlist/.test(text))) {
        const pl = await playdl.playlist_info(text, { incomplete: true });
        const vids = (await pl.all_videos()).slice(0, maxItems).map(mk).filter(s => isValidUrl(s.url));
        if (!vids.length) throw new Error('Playlist vazia ou privada.');
        return { songs: vids, playlist: pl.title || 'Playlist' };
      }
      if (kind === 'video') {
        const info = await playdl.video_info(text);
        const d = info.video_details;
        if (d.live) throw new Error('Transmissões ao vivo não são suportadas.');
        const song = mk(d);
        _musicSearchCache.set(cacheKey, { data: song, at: Date.now() });
        return { songs: [song], playlist: null };
      }
      throw new Error('Só links do YouTube são suportados. Use o nome da música para buscar.');
    }

    await sleep(200);
    const r = await playdl.search(text, { limit: 1, source: { youtube: 'video' } });
    if (!r?.length) throw new Error('Música não encontrada.');
    const song = mk(r[0]);
    _musicSearchCache.set(cacheKey, { data: song, at: Date.now() });
    if (_musicSearchCache.size > 200) {
      const cutoff = Date.now() - 5 * 60 * 1000;
      for (const [k, v] of _musicSearchCache) if (v.at < cutoff) _musicSearchCache.delete(k);
    }
    return { songs: [song], playlist: null };
  } catch (e) {
    throw new Error(e.message.startsWith('Busca falhou') ? e.message : e.message);
  }
}

// compat: versão antiga devolvia uma música só
async function buscarMusica(query, authorId) {
  const r = await resolveMusic(query, authorId, 1);
  return r.songs[0] || null;
}

function setupMusicPlayer(gid, vc, textCh) {
  const q = getQueue(gid);
  q.textChannel = textCh || q.textChannel;

  if (q.connection && q.connection.state.status === VoiceConnectionStatus.Destroyed) q.connection = null;

  if (!q.connection) {
    // a call 24/7 usa a mesma conexão do servidor: assume o controle (ao terminar a música ela é restaurada)
    const old = getVoiceConnection(gid);
    if (old && old.state.status !== VoiceConnectionStatus.Destroyed) { try { old.destroy(); } catch {} }

    const conn = joinVoiceChannel({
      channelId: vc.id, guildId: gid, adapterCreator: vc.guild.voiceAdapterCreator, selfDeaf: true,
    });
    q.connection = conn;

    conn.on(VoiceConnectionStatus.Disconnected, async () => {
      try {
        await Promise.race([
          entersState(conn, VoiceConnectionStatus.Signalling, 5000),
          entersState(conn, VoiceConnectionStatus.Connecting, 5000),
        ]);
      } catch {
        if (musicQueues.get(gid) === q && !q.destroyed) await destroyQueue(gid, 'desconectado');
      }
    });
    conn.on('error', (e) => console.error('[MUSIC-CONN]', e.message));
  }

  if (!q.player) {
    q.player = createAudioPlayer();
    q.player.on(AudioPlayerStatus.Idle, () => {
      if (q.destroyed || q.paused || !q.currentSong) return;
      tocarProxima(gid).catch(e => console.error('[MUSIC-IDLE]', e.message));
    });
    // o 'error' do player é SEGUIDO de 'Idle': só registra, quem avança é o Idle (evita pular 2 músicas)
    q.player.on('error', (e) => {
      console.error('[MUSIC-PLAYER-ERR]', e.message);
      q.failed++;
      q.currentFailed = true;
    });
  }

  // sempre (re)assina: se a conexão foi recriada o player ficava sem áudio
  try { q.connection.subscribe(q.player); } catch (e) { console.error('[MUSIC-SUB]', e.message); }
  return q;
}

function _botVoiceId(gid, q) {
  return client.guilds.cache.get(gid)?.members?.me?.voice?.channelId || q?.connection?.joinConfig?.channelId || null;
}
function _humansIn(guild, channelId) {
  const ch = guild.channels.cache.get(channelId);
  return ch ? ch.members.filter(m => !m.user.bot).size : 0;
}

// Sai da call quando todos os humanos saem (com tolerância para quem volta rápido)
function checkVoiceEmpty(guild, channelId) {
  const gid = guild.id;
  const q = musicQueues.get(gid);
  if (!q) return;
  if (_humansIn(guild, channelId) > 0) {
    const t = _musicEmptyTimers.get(gid); if (t) { clearTimeout(t); _musicEmptyTimers.delete(gid); }
    return;
  }
  if (_musicEmptyTimers.has(gid)) return;
  const timer = setTimeout(() => {
    _musicEmptyTimers.delete(gid);
    const nowQ = musicQueues.get(gid);
    if (!nowQ || nowQ !== q || nowQ.destroyed) return;
    if (_humansIn(guild, _botVoiceId(gid, nowQ) || channelId) === 0) destroyQueue(gid, 'canal vazio');
  }, MUSIC_EMPTY_MS);
  _musicEmptyTimers.set(gid, timer);
}

client.on('voiceStateUpdate', (oldS, newS) => {
  try {
    const guild = newS.guild || oldS.guild;
    const gid = guild.id;
    const q = musicQueues.get(gid);
    if (!q) return;
    if (oldS.id === client.user.id) {
      // o bot foi desconectado/expulso da call
      if (oldS.channelId && !newS.channelId && !q.destroyed) destroyQueue(gid, 'desconectado').catch(() => {});
      return;
    }
    const botCh = _botVoiceId(gid, q);
    if (!botCh) return;
    if (oldS.channelId === botCh || newS.channelId === botCh) checkVoiceEmpty(guild, botCh);
  } catch (e) { console.error('[MUSIC-VSU]', e.message); }
});

// ───────────── AÇÕES COMPARTILHADAS (slash /musica + botões + painel admin) ─────────────
// Todas devolvem { ok, content?, embeds?, components?, pub? } — pub=true: resposta pública.
const _mFail = (content) => ({ ok: false, content: `${E.x} ${content}` });

async function musicGuard(i, { control = false, needQueue = false } = {}) {
  const guild = i.guild;
  if (!guild) return { err: _mFail('Use em um servidor.') };
  const q = musicQueues.get(guild.id) || null;
  if (needQueue && (!q || (!q.currentSong && !q.songs.length))) return { err: _mFail('Não há nada tocando.') };

  const member = i.member?.voice ? i.member : await guild.members.fetch(i.user.id).catch(() => null);
  const vc = member?.voice?.channel || null;
  if (!vc) return { err: _mFail('Entre em um canal de voz primeiro.') };

  const botCh = q ? _botVoiceId(guild.id, q) : null;
  if (q && botCh && botCh !== vc.id) return { err: _mFail(`Já estou tocando em <#${botCh}>. Entre lá para usar.`) };

  if (control && q) {
    const allowed = (q.currentSong && q.currentSong.author === i.user.id)
      || _humansIn(guild, vc.id) <= 1
      || await isAdmin(i.user, guild).catch(() => false)
      || isDeveloper(i.user.id);
    if (!allowed) return { err: _mFail('Só quem pediu a música, um admin ou quem estiver sozinho na call pode fazer isso.') };
  }
  return { q, vc, guild };
}

async function musicPlay(i, query) {
  const g = await musicGuard(i);
  if (g.err) return g.err;
  const me = g.guild.members.me;
  const perms = g.vc.permissionsFor(me);
  if (!perms?.has(PermissionFlagsBits.Connect) || !perms?.has(PermissionFlagsBits.Speak)) {
    return _mFail(`Não tenho permissão de **Conectar** e **Falar** em <#${g.vc.id}>.`);
  }
  if (g.q && g.q.songs.length >= MUSIC_MAX_QUEUE) return _mFail(`A fila está cheia (${MUSIC_MAX_QUEUE} músicas).`);

  let res;
  try { res = await resolveMusic(query, i.user.id, MUSIC_MAX_QUEUE - (g.q?.songs.length || 0)); }
  catch (e) { return _mFail(e.message); }

  const q = setupMusicPlayer(g.guild.id, g.vc, i.channel);
  const room = MUSIC_MAX_QUEUE - q.songs.length;
  const songs = _stampSongs(res.songs.slice(0, Math.max(0, room)));
  if (!songs.length) return _mFail(`A fila está cheia (${MUSIC_MAX_QUEUE} músicas).`);
  q.songs.push(...songs);
  _clearMusicTimers(g.guild.id);

  const idle = q.player.state.status === AudioPlayerStatus.Idle && !q.currentSong && !q.advancing;
  if (idle) tocarProxima(g.guild.id).catch(e => console.error('[MUSIC-START]', e.message));

  if (res.playlist) {
    return { ok: true, pub: true, content: `${E.check} Playlist **${_esc(res.playlist)}** adicionada: ${songs.length} música(s).` };
  }
  const pos = idle ? 0 : q.songs.length;
  return { ok: true, pub: true, content: `${E.check} ${idle ? 'Tocando' : `Adicionada na posição **${pos}**`}: **${_esc(songs[0].title)}**` };
}

let _musicSongSeq = 0;
function _stampSongs(songs) { return songs.map(x => ({ ...x, uid: String(++_musicSongSeq) })); }

async function musicPause(i) {
  const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
  const q = g.q;
  if (!q.player || !q.currentSong) return _mFail('Não há nada tocando.');
  if (q.player.state.status === AudioPlayerStatus.Paused) {
    q.player.unpause(); q.paused = false;
    return { ok: true, pub: true, content: `${E.check} Música retomada.` };
  }
  q.player.pause(); q.paused = true;
  return { ok: true, pub: true, content: `${E.carregando} Música pausada.` };
}

async function musicSkip(i) {
  const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
  const q = g.q;
  if (!q.currentSong && !q.songs.length) return _mFail('Não há nada tocando.');
  const title = q.currentSong?.title;
  q.skipped = true;      // ignora o loop de música uma vez
  q.paused = false;      // com o player pausado o Idle era ignorado e a fila travava
  if (q.currentSong) q.player.stop(true);
  else tocarProxima(g.guild.id).catch(() => {});
  return { ok: true, pub: true, content: `${E.proximo} Pulado${title ? `: **${_esc(title)}**` : ''}.` };
}

async function musicStop(i) {
  const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
  await destroyQueue(g.guild.id, 'stop manual');
  return { ok: true, pub: true, content: `${E.lixo} Música parada e fila limpa.` };
}

async function musicLoop(i, mode = null) {
  const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
  const q = g.q;
  const valid = ['off', 'song', 'queue'];
  q.loopMode = valid.includes(mode) ? mode : (q.loopMode === 'off' ? 'song' : q.loopMode === 'song' ? 'queue' : 'off');
  const nome = { off: 'desligado', song: 'repetir música', queue: 'repetir fila' }[q.loopMode];
  return { ok: true, pub: true, content: `${E.seta} Loop: **${nome}**` };
}

async function musicVolume(i, value) {
  const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
  const v = Math.round(Number(value));
  if (!Number.isFinite(v) || v < 0 || v > 200) return _mFail('Volume inválido (use 0 a 200).');
  const q = g.q;
  q.volume = v;
  try { q.player?.state?.resource?.volume?.setVolume(v / 100); } catch {}
  return { ok: true, pub: true, content: `🔊 Volume: **${v}%**` };
}

// Botão "Play": retoma se pausado, inicia a fila se estiver parada, senão pede o que tocar
async function musicPlayButton(i) {
  const g = await musicGuard(i); if (g.err) return g.err;
  const q = g.q;
  if (q && q.player?.state?.status === AudioPlayerStatus.Paused) {
    const gc = await musicGuard(i, { control: true, needQueue: true }); if (gc.err) return gc.err;
    q.player.unpause(); q.paused = false;
    return { ok: true, pub: true, content: `${E.check} Música retomada.` };
  }
  if (q?.currentSong) {
    return { ok: true, content: `${E.emote8k} Já está tocando **${_esc(q.currentSong.title)}**. Use **Adicionar** para colocar mais músicas na fila.` };
  }
  if (q?.songs?.length) {
    setupMusicPlayer(g.guild.id, g.vc, i.channel);
    tocarProxima(g.guild.id).catch(e => console.error('[MUSIC-PLAY]', e.message));
    return { ok: true, pub: true, content: `${E.check} Iniciando a fila (${q.songs.length} música(s)).` };
  }
  return { modal: true };
}

// Lista a fila num menu para escolher qual remover (valor = id único da música)
async function musicRemoveMenu(i) {
  const g = await musicGuard(i, { needQueue: true }); if (g.err) return g.err;
  const q = g.q;
  if (!q.songs.length) return { ok: true, content: `${E.lista} A fila está vazia — não há o que remover. (A música atual você tira com **Pular**.)` };
  const menu = new StringSelectMenuBuilder().setCustomId('mus_remove_pick').setPlaceholder('Escolha a música para remover');
  menu.addOptions({ label: 'Limpar toda a fila', value: 'all', emoji: E.lixo, description: `Remove as ${q.songs.length} músicas da fila` });
  const seen = new Set();
  q.songs.slice(0, 24).forEach((sg, n) => {
    if (seen.has(sg.uid)) return; seen.add(sg.uid);
    menu.addOptions({ label: `${n + 1}. ${_esc(sg.title)}`.slice(0, 100), value: String(sg.uid), description: `Duração ${sg.duration || '?'}`.slice(0, 100) });
  });
  return { ok: true, content: `${E.remover} Qual música você quer remover da fila?`, components: [new ActionRowBuilder().addComponents(menu)] };
}

async function musicRemove(i, uid) {
  if (uid === 'all') {
    const g = await musicGuard(i, { control: true, needQueue: true }); if (g.err) return g.err;
    const n = g.q.songs.length;
    g.q.songs = [];
    if (g.q.loopMode === 'queue') g.q.loopMode = 'off';
    return { ok: true, pub: true, content: `${E.lixo} Fila limpa (${n} música(s) removida(s)).` };
  }
  const g = await musicGuard(i, { needQueue: true }); if (g.err) return g.err;
  const q = g.q;
  const song = q.songs.find(x => x.uid === String(uid));
  if (!song) return _mFail('Essa música já saiu da fila.');
  // pode remover: quem pediu a música, admin/dev ou quem está sozinho na call
  const allowed = song.author === i.user.id || _humansIn(g.guild, g.vc.id) <= 1
    || await isAdmin(i.user, g.guild).catch(() => false) || isDeveloper(i.user.id);
  if (!allowed) return _mFail('Só quem pediu a música, um admin ou quem estiver sozinho na call pode removê-la.');
  q.songs = q.songs.filter(x => x.uid !== song.uid);
  return { ok: true, pub: true, content: `${E.remover} Removida da fila: **${_esc(song.title)}**` };
}

async function musicQueueView(i) {
  const q = i.guild ? musicQueues.get(i.guild.id) : null;
  if (!q || (!q.currentSong && !q.songs.length)) return { ok: true, content: `${E.lista} A fila está vazia.` };
  const lines = q.songs.slice(0, 10).map((s, n) => `\`${n + 1}.\` ${_esc(s.title)} — \`${s.duration || '?'}\``);
  const e = new EmbedBuilder().setColor('#1DB954').setTitle(`${E.lista} Fila de músicas`)
    .setDescription([
      q.currentSong ? `${E.emote8k} **Agora:** ${_esc(q.currentSong.title)}` : '',
      lines.length ? `\n${lines.join('\n')}` : '\n*Nenhuma música na fila.*',
      q.songs.length > 10 ? `\n*...e mais ${q.songs.length - 10}*` : '',
    ].join('\n'))
    .setFooter({ text: `${q.songs.length} na fila • Loop: ${q.loopMode} • Volume ${q.volume}%` });
  return { ok: true, embeds: [e] };
}

async function musicNowPlaying(i) {
  const q = i.guild ? musicQueues.get(i.guild.id) : null;
  if (!q?.currentSong) return { ok: true, content: `${E.x} Não há nada tocando.` };
  return { ok: true, embeds: [buildNowPlayingEmbed(q, q.currentSong)], components: [musicControlRow()] };
}

// manda a resposta de uma ação (slash ou botão)
async function replyMusic(i, r, { deferred = false } = {}) {
  const payload = { content: r.content, embeds: r.embeds, components: r.components };
  if (deferred) return i.editReply(payload).catch(() => {});
  return i.reply({ ...payload, flags: (r.pub && r.ok) ? undefined : EPHEMERAL }).catch(() => {});
}

// ───────────── PREFIXO m! (qualquer membro; maiúsculas/minúsculas tanto faz) ─────────────
// m!p <busca> • m!pause • m!next • m!stop • m!queue • m!np • m!loop • m!vol • m!remove • m!clear • m!help
const MUSIC_PREFIX_RE = /^m!\s*/i;
const _musicPrefixCooldown = new Map();
const MUSIC_PREFIX_ALIASES = {
  play: ['p', 'play', 'tocar', 't'],
  pause: ['pause', 'pausar', 'resume', 'continuar', 'retomar', 'unpause'],
  skip: ['next', 'skip', 'pular', 'n', 's', 'proxima', 'próxima'],
  stop: ['stop', 'parar', 'leave', 'sair', 'dc', 'disconnect', 'desconectar'],
  queue: ['queue', 'q', 'fila', 'list', 'lista'],
  nowplaying: ['np', 'nowplaying', 'now', 'tocando', 'atual'],
  loop: ['loop', 'repetir', 'repeat'],
  volume: ['volume', 'vol', 'v'],
  remove: ['remove', 'remover', 'rm', 'del'],
  clear: ['clear', 'limpar', 'cl'],
  help: ['help', 'ajuda', 'comandos', 'h'],
};
const MUSIC_PREFIX_LOOKUP = (() => {
  const m = new Map();
  for (const [act, names] of Object.entries(MUSIC_PREFIX_ALIASES)) for (const n of names) m.set(n, act);
  return m;
})();

function buildMusicPrefixHelp() {
  return new EmbedBuilder().setColor('#1DB954').setTitle(`${E.emote8k} Comandos de música — prefixo \`m!\``)
    .setDescription([
      '*Maiúsculas ou minúsculas, tanto faz. Entre em um canal de voz antes.*',
      '',
      `${E.check} \`m!p <nome/link>\` — tocar ou adicionar à fila *(também: play)*`,
      `${E.carregando} \`m!pause\` — pausar / retomar *(m!resume)*`,
      `${E.proximo} \`m!next\` — pular *(m!skip, m!n)*`,
      `${E.lixo} \`m!stop\` — parar e limpar a fila *(m!leave, m!dc)*`,
      `${E.lista} \`m!queue\` — ver a fila *(m!q)*`,
      `${E.emote8k} \`m!np\` — música atual`,
      `${E.seta} \`m!loop [off|musica|fila]\` — repetição`,
      `${E.modo} \`m!vol <0-200>\` — volume`,
      `${E.remover} \`m!remove <posição>\` — tirar da fila *(m!rm)*`,
      `${E.lixo} \`m!clear\` — limpar a fila`,
    ].join('\n'));
}

async function _prefixReply(m, r) {
  const payload = { content: r.content || undefined, embeds: r.embeds, components: r.components, allowedMentions: { repliedUser: false, parse: [] } };
  if (!payload.content && !payload.embeds?.length) return;
  const sent = await m.reply(payload).catch(() => m.channel.send(payload).catch(() => null));
  // mensagens de erro somem sozinhas para não poluir o canal
  if (sent && r.ok === false) setTimeout(() => sent.delete().catch(() => {}), 15000);
}

async function handleMusicPrefix(m) {
  try {
    if (!m || m.author?.bot || !m.guild || !m.content) return;
    const raw = m.content.trim();
    if (!MUSIC_PREFIX_RE.test(raw)) return;

    const body = raw.replace(MUSIC_PREFIX_RE, '');
    const cmdRaw = body.split(/\s+/)[0] || '';
    const act = MUSIC_PREFIX_LOOKUP.get(cmdRaw.toLowerCase());
    if (!act) return; // "m!qualquercoisa" que não é de música: ignora em silêncio
    const rest = body.slice(cmdRaw.length).trim();

    const me = m.guild.members.me;
    if (!m.channel.permissionsFor(me)?.has(PermissionFlagsBits.SendMessages)) return;

    // anti-flood: 1 comando a cada ~1,2s por usuário
    const now = Date.now();
    if (now - (_musicPrefixCooldown.get(m.author.id) || 0) < 1200) return;
    _musicPrefixCooldown.set(m.author.id, now);
    if (_musicPrefixCooldown.size > 500) for (const [k, v] of _musicPrefixCooldown) if (now - v > 60000) _musicPrefixCooldown.delete(k);

    if (await isGlobalBanned(m.author.id).catch(() => null)) return;
    if (await isMaintenanceMode().catch(() => false) && !isDeveloper(m.author.id)) return;

    if (act === 'help') return _prefixReply(m, { ok: true, embeds: [buildMusicPrefixHelp()] });

    const tier = await getPremiumTier(m.guild.id);
    if (!(tier && tierAtLeast(tier, featureMinTier('musica')))) {
      return _prefixReply(m, { ok: false, content: `${E.trofeu} O sistema de música é um recurso **Premium** deste servidor. Peça a um admin para ativar.` });
    }
    if (!playdl) return _prefixReply(m, { ok: false, content: `${E.x} Sistema de música indisponível no momento.` });

    // mesma "interação" que o /musica e os botões usam
    const pi = { guild: m.guild, user: m.author, member: m.member, channel: m.channel };

    if (act === 'play') {
      if (!rest) {
        const q = musicQueues.get(m.guild.id);
        if (q?.player?.state?.status === AudioPlayerStatus.Paused) return _prefixReply(m, await musicPause(pi));
        return _prefixReply(m, { ok: false, content: `${E.x} Use: \`m!p <nome da música ou link>\`` });
      }
      m.channel.sendTyping?.().catch(() => {});
      return _prefixReply(m, await musicPlay(pi, rest));
    }
    if (act === 'pause') return _prefixReply(m, await musicPause(pi));
    if (act === 'skip') return _prefixReply(m, await musicSkip(pi));
    if (act === 'stop') return _prefixReply(m, await musicStop(pi));
    if (act === 'queue') return _prefixReply(m, await musicQueueView(pi));
    if (act === 'nowplaying') return _prefixReply(m, await musicNowPlaying(pi));
    if (act === 'loop') {
      const a = rest.toLowerCase();
      const mode = !a ? null
        : ['off', 'desligar', 'desligado', '0', 'nao', 'não'].includes(a) ? 'off'
        : ['song', 'musica', 'música', 'one', 'atual', '1'].includes(a) ? 'song'
        : ['queue', 'fila', 'all', 'todas'].includes(a) ? 'queue' : undefined;
      if (mode === undefined) return _prefixReply(m, { ok: false, content: `${E.x} Use: \`m!loop\` (alterna) ou \`m!loop off|musica|fila\`` });
      return _prefixReply(m, await musicLoop(pi, mode));
    }
    if (act === 'volume') {
      if (!rest) {
        const q = musicQueues.get(m.guild.id);
        return _prefixReply(m, { ok: true, content: `🔊 Volume atual: **${q?.volume ?? 100}%** — use \`m!vol <0-200>\` para mudar.` });
      }
      return _prefixReply(m, await musicVolume(pi, rest.replace('%', '')));
    }
    if (act === 'clear') return _prefixReply(m, await musicRemove(pi, 'all'));
    if (act === 'remove') {
      if (/^(all|tudo|todas)$/i.test(rest)) return _prefixReply(m, await musicRemove(pi, 'all'));
      const pos = parseInt(rest, 10);
      if (!Number.isInteger(pos) || pos < 1) return _prefixReply(m, { ok: false, content: `${E.x} Use: \`m!remove <posição>\` (veja as posições em \`m!queue\`) ou \`m!clear\`.` });
      const q = musicQueues.get(m.guild.id);
      const song = q?.songs?.[pos - 1];
      if (!song) return _prefixReply(m, { ok: false, content: `${E.x} Não há música na posição **${pos}**. Veja \`m!queue\`.` });
      return _prefixReply(m, await musicRemove(pi, song.uid));
    }
  } catch (e) {
    console.error('[MUSIC-PREFIX]', e.message);
  }
}
client.on('messageCreate', handleMusicPrefix);

async function handleMusicCommand(i) {
  if (!i.guild) return i.reply({ content: `${E.x} Use em um servidor.`, flags: EPHEMERAL });
  if (!playdl) return i.reply({ content: `${E.x} Sistema de música indisponível (play-dl não instalado).`, flags: EPHEMERAL });
  if (!await requirePremiumTier(i, 'musica')) return;
  const sub = i.options.getSubcommand();
  if (sub === 'tocar') {
    await i.deferReply();
    const r = await musicPlay(i, i.options.getString('busca', true));
    return replyMusic(i, r, { deferred: true });
  }
  if (sub === 'pausar') return replyMusic(i, await musicPause(i));
  if (sub === 'pular') return replyMusic(i, await musicSkip(i));
  if (sub === 'parar') return replyMusic(i, await musicStop(i));
  if (sub === 'loop') return replyMusic(i, await musicLoop(i, i.options.getString('modo')));
  if (sub === 'volume') return replyMusic(i, await musicVolume(i, i.options.getInteger('valor', true)));
  if (sub === 'fila') return replyMusic(i, await musicQueueView(i));
  if (sub === 'remover') {
    const q = musicQueues.get(i.guild.id);
    const song = q?.songs?.[i.options.getInteger('posicao', true) - 1];
    if (!song) return replyMusic(i, _mFail('Não há música nessa posição. Veja as posições em `/musica fila`.'));
    return replyMusic(i, await musicRemove(i, song.uid));
  }
  if (sub === 'tocando') return replyMusic(i, await musicNowPlaying(i));
}

// ═══════════════════════════════════════════════════════════
// SORTEIOS (giveaways)
// ═══════════════════════════════════════════════════════════

// ✅ FIX: Fisher-Yates real
function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

async function checkGiveaways() {
  try {
    const { data } = await supabase.from('giveaways').select('*').eq('ended', false);
    const now = Date.now();

    for (const g of data || []) {
      if (new Date(g.ends_at).getTime() > now) continue;

      let p = [];
      try { p = JSON.parse(g.participants || '[]'); } catch {}

      const ch = client.channels.cache.get(g.channel_id);
      const guild = ch?.guild;
      const validParticipants = [];
      const seen = new Set();
      for (const uid of p) {
        if (seen.has(uid)) continue;
        seen.add(uid);
        if (guild) {
          const mem = await guild.members.fetch(uid).catch(() => null);
          if (!mem) continue;
        }
        validParticipants.push(uid);
      }

      const winnersCount = Math.max(1, Number(g.winners_count) || 1);

      if (!validParticipants.length) {
        if (ch) await ch.send(`${E.x} Sem participantes válidos.`).catch(() => {});
      } else {
        const shuffled = shuffleArray(validParticipants);
        const w = shuffled.slice(0, Math.min(winnersCount, shuffled.length));
        for (const wid of w) {
          try {
            const u = await client.users.fetch(wid);
            await u.send(`${E.trofeu} Ganhou **${g.prize}**!`).catch(() => {});
            if (ch) await ch.send(`${E.trofeu} <@${wid}> ganhou **${g.prize}**!`).catch(() => {});
          } catch {}
        }
      }

      await supabase.from('giveaways').update({ ended: true }).eq('id', g.id);
    }
  } catch (e) { console.error('[GIVEAWAYS]', e.message); }
}

// ═══════════════════════════════════════════════════════════
// TEMPROLES (timeout cap 24 dias)
// ═══════════════════════════════════════════════════════════
const MAX_TIMEOUT = 2147483647;

async function scheduleTempRole(gid, uid, rid, ms) {
  try {
    await supabase.from('temproles').upsert({
      guild_id: gid, user_id: uid, role_id: rid,
      expires_at: new Date(Date.now() + ms).toISOString(),
    });
  } catch {}

  const finalize = async () => {
    const g = client.guilds.cache.get(gid);
    if (g) {
      const m = await g.members.fetch(uid).catch(() => null);
      if (m) await m.roles.remove(rid).catch(() => {});
    }
    try {
      await supabase.from('temproles').delete()
        .eq('guild_id', gid).eq('user_id', uid).eq('role_id', rid);
    } catch {}
  };

  if (ms > MAX_TIMEOUT) {
    let remaining = ms;
    const step = () => {
      if (remaining <= MAX_TIMEOUT) {
        setTimeout(finalize, remaining);
      } else {
        remaining -= MAX_TIMEOUT;
        setTimeout(step, MAX_TIMEOUT);
      }
    };
    step();
  } else {
    setTimeout(finalize, ms);
  }
}

async function checkTempRoles() {
  try {
    const { data } = await supabase.from('temproles').select('*');
    for (const e of data || []) {
      if (new Date(e.expires_at) <= new Date()) {
        const g = client.guilds.cache.get(e.guild_id);
        if (g) {
          const m = await g.members.fetch(e.user_id).catch(() => null);
          if (m) await m.roles.remove(e.role_id).catch(() => {});
        }
        await supabase.from('temproles').delete()
          .eq('guild_id', e.guild_id).eq('user_id', e.user_id).eq('role_id', e.role_id);
      }
    }
  } catch (e) { console.error('[TEMPROLES]', e.message); }
}

