async function admPanelMusica(guild) {
  const tier = await getPremiumTier(guild.id);
  const canUse = tier && tierAtLeast(tier, 'basic');
  const q = musicQueues.get(guild.id);
  const agora = q?.currentSong ? `${E.emote8k} **${_esc(q.currentSong.title)}**${q.paused ? ' *(pausada)*' : ''}` : '*nada tocando*';
  const e = new EmbedBuilder().setTitle(`${E.emote8k} Painel de Música`).setColor('#1DB954');
  if (!canUse) {
    e.setDescription(`${E.trofeu} **Recurso Premium (Basic+).** Ative em \`/dev → Gerenciamento → Premium\`.`);
  } else {
    e.setDescription([
      `**Agora:** ${agora}`,
      `**Na fila:** ${q?.songs?.length || 0} • **Loop:** ${q?.loopMode === 'song' ? 'música' : q?.loopMode === 'queue' ? 'fila' : 'desligado'} • **Volume:** ${q?.volume ?? 100}%`,
      '',
      `${E.check} **Play** — toca / retoma a fila`,
      `${E.adicionar} **Adicionar** — busca por nome, link ou playlist do YouTube`,
      `${E.remover} **Remover** — tira músicas da fila (ou limpa tudo)`,
      '',
      `*Entre em um canal de voz antes de usar. Tier: ${PREMIUM_TIERS[tier]?.label || '—'}*`,
    ].join('\n'));
  }
  return {
    embeds: [e],
    components: [
      // linha 1 — principal
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('mus_play').setLabel('Play').setEmoji(E.check).setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId('mus_add').setLabel('Adicionar').setEmoji(E.adicionar).setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('mus_remove').setLabel('Remover').setEmoji(E.remover).setStyle(ButtonStyle.Danger),
      ),
      // linha 2 — controles
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('mus_pause').setLabel('Pausar').setEmoji(E.carregando).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('mus_skip').setLabel('Pular').setEmoji(E.proximo).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('mus_stop').setLabel('Parar').setEmoji(E.lixo).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('mus_loop').setLabel('Loop').setEmoji(E.seta).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('mus_vol').setLabel('Volume').setEmoji(E.modo).setStyle(ButtonStyle.Secondary),
      ),
      // linha 3 — fila e navegação
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('mus_queue').setLabel('Ver fila').setEmoji(E.lista).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('adm_musica').setLabel('Atualizar').setEmoji(E.carregando).setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('adm_back').setLabel('Voltar').setEmoji(E.voltar).setStyle(ButtonStyle.Secondary),
      ),
    ],
  };
}

